def calculate_g_n(n):
    """Calculates g(n) using the formula g(n) = n + n * sum(k_i / p_i)."""
    if n == 1:
        return 1

    temp_n = n
    sum_k_over_p = 0
    i = 2
    while i * i <= temp_n:
        if temp_n % i == 0:
            p = i
            k = 0
            while temp_n % p == 0:
                temp_n //= p
                k += 1
            sum_k_over_p += k / p
        i += 1

    if temp_n > 1:
        # The remaining temp_n is a prime factor p_r with k_r = 1
        p = temp_n
        sum_k_over_p += 1 / p

    # g(n) = n * (1 + sum_k_over_p)
    g_n = n * (1 + sum_k_over_p)
    return int(round(g_n))

candidates = [4, 27, 3125]
results = {}
for n in candidates:
